using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CometConvergenceAction", menuName = "Data/Battle/Battle Actions/Orion/CometConvergence Action")]
public class CometConvergenceAction : PurifyCounterBasedAction
{
	[Header("Cosmic Dust Action")]
	[SerializeField]
	private DefaultEffectAction cosmicDustAction;

	[SerializeField]
	private int cosmicDustAmount;

	[SerializeField]
	private OmenLogic omenLogic;

	[Header("Star Ability")]
	[SerializeField]
	protected StarAbilityReference starAbilityReference;

	[SerializeField]
	protected StarAbility starAbilityToUse;

	public DefaultEffectAction CosmicDustAction => cosmicDustAction;

	public int CosmicDustAmount => cosmicDustAmount;

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		return starAbilityReference.Value == starAbilityToUse;
	}

	public override int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		return base.playerRunData.CosmicOrbCastedAmount;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		omenLogic.ActivateOmen(cosmicDustAction, cosmicDustAmount, null, null);
		if (PurifyCounter(checkConditionToBeCastedOrPreview: false) > 0)
		{
			base.CastTargetAmount(target, amount, source);
		}
	}
}
